INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000350', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000350","description":"飲みごたえのあるコク深いコーヒーを入れることができる豆。その\\n確かな苦味には、違いのわかるスクールアイドルも一発で虜に。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"深煎りコーヒー豆","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003083, 1, 2, 3, '深煎りコーヒー豆', 'ふかいりこーひーまめ', '飲みごたえのあるコク深いコーヒーを入れることができる豆。その\n確かな苦味には、違いのわかるスクールアイドルも一発で虜に。', 1000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000351', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000351","description":"鶴と亀があしらわれたマグカップ。長寿をはじめ、何かにつけては\\n縁起の良い代物。鶴は千年、亀は万年、スクールアイドル一億年。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ツルカメマグカップ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003084, 1, 2, 4, 'ツルカメマグカップ', 'つるかめまぐかっぷ', '鶴と亀があしらわれたマグカップ。長寿をはじめ、何かにつけては\n縁起の良い代物。鶴は千年、亀は万年、スクールアイドル一億年。', 10000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000352', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000352","description":"文房具界を激震させた脅威の消しゴム、消しゴムサウルス。小さい\\nながらも迫力あるディテールで、文字という文字を消し散らかす。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"消しゴムサウルス","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003085, 1, 2, 1, '消しゴムサウルス', 'けしごむさうるす', '文房具界を激震させた脅威の消しゴム、消しゴムサウルス。小さい\nながらも迫力あるディテールで、文字という文字を消し散らかす。', 100, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000353', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000353","description":"爽やかな味わいのラムネ。飲料のラムネばかりが青春の象徴にされ\\nがちだが、菓子のラムネのことも忘れないでほしい。美味しい。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ラムネ菓子","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003086, 1, 2, 2, 'ラムネ菓子', 'らむねがし', '爽やかな味わいのラムネ。飲料のラムネばかりが青春の象徴にされ\nがちだが、菓子のラムネのことも忘れないでほしい。美味しい。', 500, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000354', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000354","description":"大きなクジラのぬいぐるみ。その包容力に、思わず抱きつきたくな\\nること必至。そんなクジラもまた、甘えられる相手を探している。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"クジラのぬいぐるみ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003087, 1, 2, 3, 'クジラのぬいぐるみ', 'くじらのぬいぐるみ', '大きなクジラのぬいぐるみ。その包容力に、思わず抱きつきたくな\nること必至。そんなクジラもまた、甘えられる相手を探している。', 1000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000355', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000355","description":"無病息災の加護を宿したお守り。夢を叶えるべく突き進むスクール\\nアイドルを災いから守る。学業からは守ってくれない。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"無病息災のお守り","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003088, 1, 2, 4, '無病息災のお守り', 'むびょうそくさいのおまもり', '無病息災の加護を宿したお守り。夢を叶えるべく突き進むスクール\nアイドルを災いから守る。学業からは守ってくれない。', 10000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000356', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000356","description":"七色に光り輝くいちごミルク。誰もがその目を疑った。だがゲーム\\nとは、常に自分自身との戦い。常識を覆し、限界を突破しよう。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ゲーミングいちごミルク","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003089, 1, 2, 1, 'ゲーミングいちごミルク', 'げーみんぐいちごみるく', '七色に光り輝くいちごミルク。誰もがその目を疑った。だがゲーム\nとは、常に自分自身との戦い。常識を覆し、限界を突破しよう。', 100, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000357', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000357","description":"ケーキを模したキャップ。使わないコンセントの穴に挿して使う。\\n電流には蓋をできるが、ケーキを食べる欲望には蓋をできない。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ケーキのコンセントキャップ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003090, 1, 2, 2, 'ケーキのコンセントキャップ', 'けーきのこんせんときゃっぷ', 'ケーキを模したキャップ。使わないコンセントの穴に挿して使う。\n電流には蓋をできるが、ケーキを食べる欲望には蓋をできない。', 500, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000358', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000358","description":"ウミウシのやわらかスクイーズ。にぎにぎすることで、心を落ち着\\nけることができる。敗北続きで冷静さを失った時、握っておこう。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ウミウシのスクイーズ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003091, 1, 2, 3, 'ウミウシのスクイーズ', 'うみうしのすくいーず', 'ウミウシのやわらかスクイーズ。にぎにぎすることで、心を落ち着\nけることができる。敗北続きで冷静さを失った時、握っておこう。', 1000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-000000000359', '{"d_item_datas_id":"00000000-0000-0000-0000-000000000359","description":"慈と瑠璃乃のアクリルスタンド。置くだけで、いつでもどこでも、\\nみらくらぱーく！らしい。いくらあっても良いとされている。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"めぐるりアクスタ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003092, 1, 2, 4, 'めぐるりアクスタ', 'めぐるりあくすた', '慈と瑠璃乃のアクリルスタンド。置くだけで、いつでもどこでも、\nみらくらぱーく！らしい。いくらあっても良いとされている。', 10000, 9999, 0, '2024-04-12 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035a', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035a","description":"一瞬で牛丼を用意できるパック。牛丼屋なんてどこにでもあると思\\nうかもしれないが、蓮ノ空には通用しない。これは\"救い\"。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"レトルト牛丼","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003101, 1, 2, 1, 'レトルト牛丼', 'れとるとぎゅうどん', '一瞬で牛丼を用意できるパック。牛丼屋なんてどこにでもあると思\nうかもしれないが、蓮ノ空には通用しない。これは"救い"。', 100, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035b', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035b","description":"お風呂をフローラルの香りでいっぱいにできるバスボム。その香り\\nと色、成分で極上のリラックスを提供してくれる。サンクス。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"フローラルバスボム","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003102, 1, 2, 2, 'フローラルバスボム', 'ふろーらるばすぼむ', 'お風呂をフローラルの香りでいっぱいにできるバスボム。その香り\nと色、成分で極上のリラックスを提供してくれる。サンクス。', 500, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035c', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035c","description":"握りこむことでドリンクをゴクゴク飲めるボトル。動きながらでも\\n飲みたいだけ飲めてこぼれない。今日からあなたもスクイズボトル。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"スタイリッシュスクイズボトル","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003103, 1, 2, 3, 'スタイリッシュスクイズボトル', 'すたいりっしゅすくいずぼとる', '握りこむことでドリンクをゴクゴク飲めるボトル。動きながらでも\n飲みたいだけ飲めてこぼれない。今日からあなたもスクイズボトル。', 1000, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035d', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035d","description":"様々なファッションを一目で確認できるカタログ。その組み合わせ\\nは無限大、何を選ぶかが運命を決める、そんな情熱がほとばしる。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"ファッションカタログ","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003104, 1, 2, 4, 'ファッションカタログ', 'ふぁっしょんかたろぐ', '様々なファッションを一目で確認できるカタログ。その組み合わせ\nは無限大、何を選ぶかが運命を決める、そんな情熱がほとばしる。', 10000, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035e', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035e","description":"キャラメルでコーティングされたポップコーン。映画鑑賞のお供と\\nして右に出るものはいない。お腹も出ないように気を付けよう。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"キャラメルポップコーン","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003111, 1, 2, 1, 'キャラメルポップコーン', 'きゃらめるぽっぷこーん', 'キャラメルでコーティングされたポップコーン。映画鑑賞のお供と\nして右に出るものはいない。お腹も出ないように気を付けよう。', 100, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
INSERT OR REPLACE INTO item (d_item_datas_id, response_json, item_id, item_type, item_category, rarity, name, name_furigana, description, effect_value, limit_num, requestable_num, start_time, end_time, item_num, limit_date_time, quest_list, resource_file_name, transition_scene) VALUES ('00000000-0000-0000-0000-00000000035f', '{"d_item_datas_id":"00000000-0000-0000-0000-00000000035f","description":"ヴァイオリンをチューニングするためのチューナー。人の心を動かす\\n美しい演奏は正しい音程から。聞かせよう、蓮ノ空の協奏を――。","item_num":9999,"item_type":1,"limit_date_time":null,"name":"チューナー","quest_list":[],"resource_file_name":"","transition_scene":""}', 2003112, 1, 2, 2, 'チューナー', 'ちゅーなー', 'ヴァイオリンをチューニングするためのチューナー。人の心を動かす\n美しい演奏は正しい音程から。聞かせよう、蓮ノ空の協奏を――。', 500, 9999, 0, '2025-04-09 15:00:00+00:00', '2035-12-31 14:59:59+00:00', 9999, NULL, '[]', '', '');
